mapper.select:
SELECT e.id, e.member_id, m.name as member_name, m.phone as member_phone, e.schedule_id, c.id as course_id, c.name as course_name, c.duration, c.price, co.id as coach_id, co.name as coach_name, s.class_time, s.day_of_week, s.start_time, s.end_time, e.status, e.create_time FROM gym_course_enrollment e LEFT JOIN gym_member m ON e.member_id = m.id LEFT JOIN gym_class_schedule s ON e.schedule_id = s.id LEFT JOIN gym_course c ON s.course_id = c.id LEFT JOIN gym_coach co ON s.coach_id = co.id WHERE e.deleted = 0 AND e.member_id = #{memberId}
AND e.status = #{status}
ORDER BY e.create_time DESC

SELECT e.id, e.member_id, m.name as member_name, m.phone as member_phone, e.schedule_id, c.id as course_id, c.name as course_name, c.duration, c.price, co.id as coach_id, co.name as coach_name, s.class_time, s.day_of_week, s.start_time, s.end_time, e.status, e.create_time FROM gym_course_enrollment e LEFT JOIN gym_member m ON e.member_id = m.id LEFT JOIN gym_class_schedule s ON e.schedule_id = s.id LEFT JOIN gym_course c ON s.course_id = c.id LEFT JOIN gym_coach co ON s.coach_id = co.id WHERE e.deleted = 0
AND e.member_id = #{query.memberId}
AND c.id = #{query.courseId}
AND co.id = #{query.coachId}
AND e.status = #{query.status}
AND s.class_time >= #{query.startDate}
AND s.class_time <= #{query.endDate}
ORDER BY e.create_time DESC
